                                       :SignedL1UncertaintySetAlgorithm),
                                   Cap(:ActiveAssetsUncertaintyAlgorithm)]),
                            Prose("One estimator reads no returns at all. It receives the fitted prior of its optimisation, and it limits both of its sets to the directions that the factor model of the prior does not span."),
                            Group(Cap(:OrthogonalUncertaintySet),
                                  [Group("Orthogonality metrics, the cross-sectional weights under which the span of the factors is computed",
                                         [Cap(:InverseIdiosyncraticVarianceMetric),
                                          Cap(:RegressionWeightMetric),
                                          Cap(:BenchmarkWeightMetric),
                                          Cap(:IdentityMetric)]),
